SELECT id, parentId, name, url, material_number, brand, description, number, vault, deleteSign, unit, priceUnit FROM product WHERE id=#{id} and vault = #{vault}
UNION ALL
SELECT id AS id, fin_sort_id AS parentId, fin_product_name AS name, url AS url, fin_material_number AS material_number, price AS brand, fin_description AS description, fin_number AS number, vault AS vault, deleteSign AS deleteSign, unit AS unit, priceUnit AS priceUnit FROM fin_product WHERE id=#{id} and vault = #{vault}
